# ============================================================================
#  ZENITH ORBITRON - GROUND STATION v7.0            SINGLE-FILE DISTRIBUTION
# ============================================================================
#  This file is self-contained: the application below is the original
#  ground-station GUI, and the "zenith" communication package it imports is
#  embedded here as source (see _ZENITH_MODULE_SOURCES further down).
#
#  Run it with:      python zenith_gs_standalone.py
#  Requirements:     pip install -r requirements.txt
#
#  Generated by tools/make_standalone.py - edit the sources in zenith/ and
#  regenerate rather than editing the embedded copies.
# ============================================================================

import sys as _zenith_sys
import types as _zenith_types


def _zenith_register():
    """Create the ``zenith`` package in memory from the embedded sources."""
    package = _zenith_types.ModuleType("zenith")
    package.__path__ = []                    # mark it as a package
    package.__version__ = "7.0.0"
    _zenith_sys.modules["zenith"] = package

    for name, source in _ZENITH_MODULE_SOURCES.items():
        module = _zenith_types.ModuleType("zenith." + name)
        module.__file__ = f"<zenith_gs_standalone:zenith/{name}.py>"
        module.__package__ = "zenith"
        # register BEFORE executing so relative imports can resolve
        _zenith_sys.modules["zenith." + name] = module
        setattr(package, name, module)
        try:
            exec(compile(source, module.__file__, "exec"), module.__dict__)
        except Exception as exc:             # pragma: no cover
            del _zenith_sys.modules["zenith." + name]
            if name != "deps":               # deps is optional, the rest is not
                raise RuntimeError(
                    f"failed to initialise embedded module zenith.{name}: "
                    f"{exc!r}") from exc
    return package


