class LogoBannerLabel(QLabel):
    """NEW: centre banner of the first dashboard's logo header.
    It fills all the free space between the two side logos (white backdrop that
    matches the banner artwork) and re-scales the banner on every resize so it
    is always as large as fits, with the original aspect ratio (never stretched)."""

    def __init__(self, b64_data, height_px, parent=None):
        super().__init__(parent)
        self._src = QPixmap()
        try:
            self._src.loadFromData(base64.b64decode(b64_data))
        except Exception:
            self._src = QPixmap()
        self.setFixedHeight(height_px)
        self.setMinimumWidth(1)
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Fixed)
        self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setStyleSheet("background-color: #FFFFFF;")

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if self._src.isNull():
            return
        dpr = self.devicePixelRatioF()
        w = max(1, int(self.width() * dpr))
        h = max(1, int(self.height() * dpr))
        pm = self._src.scaled(w, h, Qt.AspectRatioMode.KeepAspectRatio,
                              Qt.TransformationMode.SmoothTransformation)
        pm.setDevicePixelRatio(dpr)
        self.setPixmap(pm)


class GroundStationGUI(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle("IN-SPACe 2026 — Zenith Orbitron Ground Station")
        self.resize(1500, 950)

        # --- v7.0: ONE shared telemetry store -----------------------------
        # self.hist shares the very same deque objects as the store, so the
        # graphs, the labels, the CSV log, the map and both simulations all
        # read from a single validated source.  There is no second copy.
        self.store = TelemetryStore()
        self.hist = dict(self.store.history)
        self.hist["t"] = self.store.t

        self.packet_loss = PacketLossTracker()
        self.attitude = AttitudeEstimator()
        self.derived = {"roll": float("nan"),
                        "pitch": float("nan"),
                        "yaw": float("nan")}

        self.packet_count = 0
        self.total_packet_bytes = 0
        self.last_packet_size = 0
        self.last_packet_wall = None
        self.start_wall = time.time()
        self.max_alt = float("-inf")
        self.max_accel = 0.0
        self.auto_scroll = True
        self.hil_frames = None             # set while a HIL self test runs

        # map state
        self.map_marker_lat = None
        self.map_marker_lon = None
        self.map_view = None
        self.map_fullscreen_dialog = None
        self.last_map_render = 0.0

        # CSV log - every column of the channel table is written; a channel the
        # firmware does not transmit is logged as an EMPTY cell (never 0, never
        # "nan"), so a recorded flight can be replayed without inventing data.
        self.csv_filename = f"telemetry_{int(time.time())}.csv"
        self.csv_logger = CsvLogger(self.csv_filename)

        self.thread = None
        self.init_ui()

        # link watchdog
        from PyQt6.QtCore import QTimer
        self.watchdog = QTimer(self)
        self.watchdog.timeout.connect(self._check_link)
        self.watchdog.start(500)

    # ---------------------------------------------------------
    # UI
    # ---------------------------------------------------------
    def init_ui(self):
        central = QWidget()
        main = QVBoxLayout(central)

        # The original dashboard is placed inside a resizable scroll area so
        # all dashboard controls remain reachable on smaller screens.
        # The dashboard widgets and their behavior are otherwise unchanged.
        dashboard_scroll = QScrollArea()
        dashboard_scroll.setWidgetResizable(True)
        dashboard_scroll.setHorizontalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        dashboard_scroll.setVerticalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        dashboard_scroll.setFrameShape(QScrollArea.Shape.NoFrame)
        dashboard_scroll.setWidget(central)

        self.tabs = QTabWidget()
        self.tabs.setStyleSheet(
            "QTabWidget::pane { border: 1px solid #383838; }"
            "QTabBar::tab { background-color: #1B1B1B; border: 1px solid #383838;"
            " padding: 6px 18px; }"
            "QTabBar::tab:selected { background-color: #272727; color: #00FFCC; }"
            "QTabBar::tab:hover { background-color: #272727; }")
        self.tabs.addTab(dashboard_scroll, "Telemetry Dashboard")
        self.setCentralWidget(self.tabs)

        # ---- NEW: logo header (top-left + top-right of the first dashboard) ----
        logo_row = QHBoxLayout()
        logo_row.setContentsMargins(0, 0, 0, 0)
        logo_row.addWidget(self._make_logo_label(LOGO_LEFT_B64),
                           0, Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop)
        logo_row.addWidget(LogoBannerLabel(LOGO_BANNER_B64, LOGO_HEIGHT_PX), 1)
        logo_row.addWidget(self._make_logo_label(LOGO_RIGHT_B64),
                           0, Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignTop)
        main.addLayout(logo_row)

        # ---- top bar ----
        top = QHBoxLayout()
        self.port_selector = QComboBox()
        self.baud_selector = QComboBox()
        self.baud_selector.addItems(BAUD_CHOICES)
        self.baud_selector.setCurrentText(DEFAULT_BAUD)
        btn_refresh = QPushButton("Refresh Ports")
        btn_refresh.clicked.connect(self.refresh_ports)
        self.btn_connect = QPushButton("Connect Serial")
        self.btn_connect.clicked.connect(self.toggle_connection)
        self.status_label = QLabel("Status: DISCONNECTED")
        self.status_label.setStyleSheet("color: #FF3333; font-weight: bold;")
        self.link_label = QLabel("LoRa link: --")
        self.link_label.setStyleSheet("color: #888888; font-weight: bold;")

        top.addWidget(QLabel("COM Port:"))
        top.addWidget(self.port_selector)
        top.addWidget(QLabel("Baud:"))
        top.addWidget(self.baud_selector)
        top.addWidget(btn_refresh)
        top.addWidget(self.btn_connect)
        top.addWidget(self.status_label)
        top.addWidget(self.link_label)
        # --- v7.0: two tools that verify the link without hardware ----------
        self.btn_replay = QPushButton("Replay Log …")
        self.btn_replay.setToolTip(
            "Play a saved receiver log through the same decoder and the same "
            "graphs / map / simulations as a live link.")
        self.btn_replay.clicked.connect(self._on_replay)
        self.btn_hil = QPushButton("HIL Self-Test")
        self.btn_hil.setToolTip(
            "Hardware-In-The-Loop: sends reference frames into the open port "
            "and checks that they come back decoded. Verification only - the "
            "values it sends are never shown as flight telemetry.")
        self.btn_hil.clicked.connect(self._on_hil)
        top.addWidget(self.btn_replay)
        top.addWidget(self.btn_hil)
        top.addStretch()
        main.addLayout(top)

        # ---- metrics row ----
        metrics = QHBoxLayout()

        def box(title, labels_grid):
            gb = QGroupBox(title)
            g = QGridLayout(gb)
            for lbl, r, c in labels_grid:
                g.addWidget(lbl, r, c)
            return gb

        self.lbl_bmp = QLabel("Alt 0.00 m | 0.00 °C | 0.00 hPa")
        self.lbl_bmp.setStyleSheet("color: #00FFCC; font-weight: bold;")
        self.lbl_dps = QLabel("not transmitted")
        self.lbl_dps.setStyleSheet("color: #FF8A00; font-weight: bold;")
        self.lbl_alt_diff = QLabel("ΔAlt (BMP−DPS): -- m")
        self.lbl_max_alt = QLabel("Max Alt: 0.00 m")
        metrics.addWidget(box("BAROMETERS  (BMP390L fitted / DPS310 not fitted)", [
            (QLabel("BMP390L:"), 0, 0), (self.lbl_bmp, 0, 1),
            (QLabel("DPS310:"), 1, 0), (self.lbl_dps, 1, 1),
            (self.lbl_alt_diff, 2, 0), (self.lbl_max_alt, 2, 1)]))

        self.lbl_accel = QLabel("Accel: X 0.00 | Y 0.00 | Z 0.00 m/s²")
        self.lbl_gyro = QLabel("Gyro: X 0.00 | Y 0.00 | Z 0.00 °/s")
        self.lbl_euler = QLabel("Roll +0.0° | Pitch +0.0° | Yaw +0.0°")
        self.lbl_accel_mag = QLabel("|a|: 0.00 m/s² (max 0.00)")
        metrics.addWidget(box("BNO085 IMU  (roll/pitch/yaw derived, not transmitted)", [
            (self.lbl_accel, 0, 0), (self.lbl_gyro, 1, 0),
            (self.lbl_euler, 2, 0), (self.lbl_accel_mag, 3, 0)]))

        self.lbl_vbus = QLabel("Bus: 0.00 V")
        self.lbl_vbus.setStyleSheet(
            "color: #B388FF; font-size: 13pt; font-weight: bold;")
        self.lbl_cur = QLabel("Current: -- mA (not transmitted)")
        self.lbl_pwr = QLabel("Power: -- mW (not transmitted)")
        metrics.addWidget(box("INA219 POWER  (only bus voltage is transmitted)", [
            (self.lbl_vbus, 0, 0), (self.lbl_cur, 1, 0),
            (self.lbl_pwr, 2, 0)]))

        self.lbl_packet_count = QLabel("Packets: 0")
        self.lbl_packet_rate = QLabel("Rate: 0.00 Hz")
        self.lbl_last_packet = QLabel("Last Packet: --")
        self.lbl_time = QLabel("Flight Time: 0.00 s")
        self.lbl_packet_size = QLabel("Last Size: 0 B")
        self.lbl_avg_size = QLabel("Average Size: 0.0 B")
        metrics.addWidget(box("LoRa TELEMETRY LINK", [
            (self.lbl_packet_count, 0, 0), (self.lbl_packet_rate, 0, 1),
            (self.lbl_last_packet, 1, 0), (self.lbl_time, 1, 1),
            (self.lbl_packet_size, 2, 0), (self.lbl_avg_size, 2, 1)]))
        main.addLayout(metrics)

        # ---- sidebar + graph grid ----
        pg.setConfigOption("background", "#121212")
        pg.setConfigOption("foreground", "#FFFFFF")

        row = QHBoxLayout()

        side = QWidget()
        side.setMaximumWidth(300)
        side_l = QVBoxLayout(side)
        side_l.setSpacing(6)

        gb_att = QGroupBox("FLIGHT ATTITUDE INDICATOR")
        l_att = QVBoxLayout(gb_att)
        self.attitude_indicator = AttitudeIndicator()
        self.attitude_indicator.setFixedHeight(190)
        l_att.addWidget(self.attitude_indicator)
        side_l.addWidget(gb_att)

        gb_map = QGroupBox("PAYLOAD LOCATION")
        l_map = QVBoxLayout(gb_map)
        map_widget = self._build_map_widget()
        map_widget.setFixedHeight(190)
        l_map.addWidget(map_widget)
        side_l.addWidget(gb_map)
        side_l.addStretch()
        row.addWidget(side)

        graphs = QWidget()
        grid = QGridLayout(graphs)
        grid.setSpacing(6)
        grid.setContentsMargins(0, 0, 0, 0)

        self.plots = {}
        self.curves = {}   # plot id -> [(key, curve)]
        self.plot_notes = {}   # plot id -> pg.TextItem shown when nothing arrives
        self.plot_note_text = {}   # plot id -> notice text ("" = never show)
        for n, (pid, title, ylabel, units, series) in enumerate(PLOT_SPECS):
            pw = pg.PlotWidget(title=title)
            pw.setLabel("left", ylabel, units=units)
            pw.setLabel("bottom", "Flight Time", units="s")
            pw.showGrid(x=True, y=True, alpha=0.25)
            pw.setBackground("#121212")
            pw.setMinimumHeight(150)
            pw.getPlotItem().getAxis("left").setWidth(70)
            if len(series) > 1:
                pw.addLegend()
            pw.setXRange(0, 10, padding=0)
            pw.setYRange(0, 10, padding=0)
            self.plots[pid] = pw
            self.curves[pid] = []
            for key, color, name in series:
                # v7.0: a channel that is only derived from other real data is
                # drawn dashed, so it can never be mistaken for a measurement.
                derived = key in DERIVED_KEYS
                pen = pg.mkPen(color=color, width=2,
                               style=Qt.PenStyle.DashLine if derived
                               else Qt.PenStyle.SolidLine)
                curve = pw.plot(pen=pen, name=name)
                self.curves[pid].append((key, curve))
            # v7.0: on-canvas notice for tiles whose channels are not on the
            # wire.  The tile keeps its place in the 4x2 grid (layout intact).
            if any(k in DERIVED_KEYS for k, _c, _n in series):
                note_text = DERIVED_TEXT
            elif all(k in CHANNELS_NOT_TRANSMITTED for k, _c, _n in series):
                note_text = NOT_TRANSMITTED_TEXT
            else:
                note_text = ""
            note = pg.TextItem(note_text, color="#FF8A00", anchor=(0.5, 0.5))
            note.setVisible(bool(note_text))
            pw.addItem(note)
            self.plot_notes[pid] = note
            self.plot_note_text[pid] = note_text
            gb = QGroupBox(title.upper())
            QVBoxLayout(gb).addWidget(pw)
            grid.addWidget(gb, n // 4, n % 4)
        for i in range(4):
            grid.setColumnStretch(i, 1)
        grid.setRowStretch(0, 1)
        grid.setRowStretch(1, 1)
        row.addWidget(graphs, 1)
        main.addLayout(row, 1)

        # ---- console (Serial Monitor) ----
        # v7.0: the only layout change in the whole dashboard - the monitor is
        # taller so a full receiver report block is readable, and it has an
        # explicit auto-scroll switch.  Everything else is untouched.
        self.console = QTextEdit()
        self.console.setReadOnly(True)
        self.console.setMaximumHeight(240)
        self.console.document().setMaximumBlockCount(1500)
        self.console.setStyleSheet(
            "background-color:#000000; color:#00FF00;"
            "font-family:Consolas; font-size:10pt;")
        main.addWidget(self.console)

        console_tools = QHBoxLayout()
        self.chk_autoscroll = QCheckBox("Auto-scroll Serial Monitor")
        self.chk_autoscroll.setChecked(True)
        self.chk_autoscroll.stateChanged.connect(
            lambda _s: setattr(self, "auto_scroll",
                               self.chk_autoscroll.isChecked()))
        self.btn_clear_console = QPushButton("Clear Monitor")
        self.btn_clear_console.clicked.connect(self.console.clear)
        console_tools.addWidget(self.chk_autoscroll)
        console_tools.addWidget(self.btn_clear_console)
        console_tools.addStretch()
        main.addLayout(console_tools)

        self._log(f"[SYSTEM] {VERSION}")
        self._log("[SYSTEM] Rocket TX frame: '@' + 15 CSV fields + '\\n'")
        self._log("[SYSTEM]   TEAM_ID,ms,count,alt_m,press_hPa,temp_C,volt_V,"
                  "gnssTime,lat,lon,gnssAlt_m,sats,ax;ay;az,gx;gy;gz,state")
        self._log("[SYSTEM] Accepted: receiver report block | RX,<15 fields> | "
                  "raw '@' frame | legacy CAN,20/22 fields")
        self._log("[SYSTEM] Not transmitted by this firmware: "
                  + ", ".join(c.name for c in ZCFG.missing_channels()))
        self._log(f"[SYSTEM] Logging to {self.csv_filename}")
        self._log("[SYSTEM] Select COM port and press Connect Serial.")
        self._place_plot_notes()
        self._init_extra_tabs()   # NEW: adds tab 2 (Live Map) + tab 3 (Simulation)
        self.refresh_ports()

    # ---------------------------------------------------------
    # NEW — LOGO HELPER
    # ---------------------------------------------------------
    def _make_logo_label(self, b64_data):
        """QLabel showing an embedded (base64 PNG) logo scaled to LOGO_HEIGHT_PX
        with its aspect ratio preserved. If decoding ever fails the label is
        simply blank (same size), so the application still runs."""
        lbl = QLabel()
        lbl.setFixedHeight(LOGO_HEIGHT_PX)
        lbl.setMinimumWidth(1)
        lbl.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        pm = QPixmap()
        try:
            pm.loadFromData(base64.b64decode(b64_data))
        except Exception:
            pm = QPixmap()
        if not pm.isNull():
            dpr = self.devicePixelRatioF()
            target = int(LOGO_HEIGHT_PX * dpr)
            # Scale the complete logo to the larger header height without
            # stretching or distorting its original aspect ratio.
            pm = pm.scaled(target, target,
                           Qt.AspectRatioMode.KeepAspectRatio,
                           Qt.TransformationMode.SmoothTransformation)
            pm.setDevicePixelRatio(dpr)
            lbl.setPixmap(pm)
            lbl.setFixedSize(max(1, int(pm.width() / dpr)), LOGO_HEIGHT_PX)
        return lbl

    # ---------------------------------------------------------
    # NEW — EXTRA TABS
    # ---------------------------------------------------------
    def _init_extra_tabs(self):
        self.map_tab = LiveMapTab()                 # Existing map tab
        self.sim_tab = RocketSimulationTab()        # Existing 2D simulation tab
        self.sim3d_tab = Rocket3DSimulationTab()     # NEW TAB 4: STL-based 3D view
        self.tabs.addTab(self.map_tab, "Live Map")
        self.tabs.addTab(self.sim_tab, "2D Flight Simulation")
        self.tabs.addTab(self.sim3d_tab, "3D Rocket Simulation")
        self._log(
            "[SYSTEM] Existing Live Map + 2D Flight Simulation tabs initialized; "
            "new STL-based 3D Rocket Simulation tab added as tab 4.")

    def _feed_new_tabs(self, pkt):
        """Forward the same parsed packet to the map and both simulations.
        Each tab is isolated so its errors cannot affect serial/telemetry logic."""
        try:
            self.map_tab.update_from_packet(pkt)
        except Exception as e:
            self._log(f"[MAP TAB ERROR] {type(e).__name__}: {e}")
        try:
            self.sim_tab.update_from_packet(pkt)
        except Exception as e:
            self._log(f"[SIM TAB ERROR] {type(e).__name__}: {e}")
        try:
            self.sim3d_tab.update_from_packet(pkt)
        except Exception as e:
            self._log(f"[3D SIM TAB ERROR] {type(e).__name__}: {e}")

    # ---------------------------------------------------------
    # MAP
    # ---------------------------------------------------------
    def _build_map_widget(self):
        container = QWidget()
        stack = QStackedLayout(container)
        stack.setStackingMode(QStackedLayout.StackingMode.StackAll)
        stack.setContentsMargins(0, 0, 0, 0)

        if MAP_SUPPORT_AVAILABLE:
            self.map_view = QWebEngineView()
            self._render_map(self.map_view)
            stack.addWidget(self.map_view)
        else:
            fb = QLabel("Map unavailable —\ninstall with:\n"
                        "pip install folium PyQt6-WebEngine")
            fb.setAlignment(Qt.AlignmentFlag.AlignCenter)
            fb.setStyleSheet("color: #FF8A00;")
            stack.addWidget(fb)

        overlay = ClickableMapOverlay()
        overlay.clicked.connect(self._open_map_fullscreen)
        stack.addWidget(overlay)
        return container

    def _build_folium_html(self):
        lat = self.map_marker_lat
        lon = self.map_marker_lon
        fmap = folium.Map(
            location=[lat if lat is not None else MAP_DEFAULT_LAT,
                      lon if lon is not None else MAP_DEFAULT_LON],
            zoom_start=15, tiles="OpenStreetMap")
        if lat is not None:
            folium.Marker(
                [lat, lon], tooltip="Payload location",
                icon=folium.Icon(color="red", icon="rocket", prefix="fa")
            ).add_to(fmap)
        return fmap.get_root().render()

    def _render_map(self, view):
        view.setHtml(self._build_folium_html())

    def _open_map_fullscreen(self):
        if not MAP_SUPPORT_AVAILABLE:
            QMessageBox.information(
                self, "Map Unavailable",
                "pip install folium PyQt6-WebEngine")
            return
        if self.map_marker_lat is None:
            QMessageBox.information(
                self, "GPS Location Unavailable",
                "The locator appears once valid latitude/longitude "
                "arrive in the telemetry.")
            return
        d = self.map_fullscreen_dialog
        if d is not None and d.isVisible():
            d.raise_()
            d.activateWindow()
            return
        self.map_fullscreen_dialog = MapFullscreenDialog(
            self._build_folium_html(), parent=self)
        self.map_fullscreen_dialog.finished.connect(
            lambda _=None: setattr(self, "map_fullscreen_dialog", None))

    def _update_map_location(self, lat, lon):
        if not MAP_SUPPORT_AVAILABLE:
            return
        self.map_marker_lat, self.map_marker_lon = lat, lon
        now = time.time()
        if now - self.last_map_render < MAP_REFRESH_S:
            return
        self.last_map_render = now
        if self.map_view is not None:
            self._render_map(self.map_view)
        d = self.map_fullscreen_dialog
        if d is not None and d.isVisible():
            d.view.setHtml(self._build_folium_html())

    # ---------------------------------------------------------
    # PORTS / CONNECTION
    # ---------------------------------------------------------
    def refresh_ports(self):
        current = self.port_selector.currentText()
        self.port_selector.clear()
        # v7.0: port enumeration must never be able to crash the dashboard
        ports, descriptions = [], {}
        try:
            if SERIAL_LIBRARY_AVAILABLE:
                for p in serial.tools.list_ports.comports():
                    ports.append(p.device)
                    descriptions[p.device] = p.description or "Unknown device"
        except Exception as e:
            self._log(f"[PORT] port enumeration failed: {e}", "#FF8A00")
        if not ports:                      # fallback scan (e.g. odd udev setups)
            ports = available_ports()
            descriptions = {d: "found by device scan" for d in ports}
        if not ports:
            self.port_selector.addItem("NO SERIAL PORTS FOUND")
            self._log("[PORT] No serial ports detected.", "#FF8A00")
            return
        for device in ports:
            self.port_selector.addItem(device)
        i = self.port_selector.findText(current)
        if i >= 0:
            self.port_selector.setCurrentIndex(i)
        self._log("[PORT] Available serial ports:", "#9E9E9E")
        for device in ports:
            self._log(f"    {device} — "
                      f"{descriptions.get(device, 'Unknown device')}", "#9E9E9E")

    def toggle_connection(self):
        if self.thread is not None and self.thread.isRunning():
            self._log("[SERIAL] Disconnecting...")
            self.thread.stop()
            self.thread = None
            self._set_status("DISCONNECTED", "#FF3333")
            self.btn_connect.setText("Connect Serial")
            return

        port = self.port_selector.currentText()
        if not port or port == "NO SERIAL PORTS FOUND":
            QMessageBox.warning(self, "No Serial Port",
                                "No valid serial port is selected.")
            return
        baud = int(self.baud_selector.currentText())

        # reset stats + history
        self.packet_count = 0
        self.total_packet_bytes = 0
        self.last_packet_size = 0
        self.last_packet_wall = None
        self.start_wall = time.time()
        self.max_alt = float("-inf")
        self.max_accel = 0.0
        for d in self.hist.values():
            d.clear()
        for lst in self.curves.values():
            for _, c in lst:
                c.setData([], [])
        self.attitude_indicator.set_attitude(0, 0, 0)

        # --- v7.0: reset the shared store and the derived estimators -------
        self.store.clear()
        self.packet_loss.reset()
        self.attitude.reset()
        self.derived = {"roll": float("nan"),
                        "pitch": float("nan"),
                        "yaw": float("nan")}
        for pid, note in self.plot_notes.items():
            if note is not None and self.plot_note_text.get(pid):
                note.setVisible(True)
        self._set_status(f"CONNECTING ({port})", "#FFFF00")

        self._log(f"[SERIAL] Connecting to {port} @ {baud} baud ...")
        self.thread = SerialReaderThread(port, baud)
        self.thread.telemetry_packet_signal.connect(self.handle_telemetry_packet)
        self.thread.raw_console_signal.connect(
            lambda text: self._log(text, "#9E9E9E"))
        self.thread.monitor_line_signal.connect(
            lambda text: self._log(text, "#00FF00"))
        self.thread.decoder_message_signal.connect(
            lambda level, text: self._log(
                text, {"error": "#FF3333", "warn": "#FF8A00"}.get(level, "#9E9E9E")))
        self.thread.connection_error_signal.connect(self.handle_connection_error)
        self.thread.connection_status_signal.connect(self.handle_connection_status)
        self.thread.start()

        self.btn_connect.setText("Disconnect")
        self._set_status(f"CONNECTING ({port})", "#FFFF00")

    def _set_status(self, text, color):
        self.status_label.setText(f"Status: {text}")
        self.status_label.setStyleSheet(f"color: {color}; font-weight: bold;")

    def handle_connection_status(self, status):
        self._log(f"[STATUS] {status}")
        if status.startswith("CONNECTED"):
            self._set_status(status, "#00FFCC")
        elif status == "DISCONNECTED":
            self._set_status("DISCONNECTED", "#FF3333")
            self.btn_connect.setText("Connect Serial")

    def handle_connection_error(self, message):
        self._log(f"[ERROR] {message}")
        self._set_status("SERIAL ERROR", "#FF3333")
        self.btn_connect.setText("Connect Serial")
        QMessageBox.critical(self, "Serial Connection Error", message)

    def _check_link(self):
        if self.last_packet_wall is None:
            return
        age = time.time() - self.last_packet_wall
        if age > LINK_LOST_TIMEOUT_S:
            self.link_label.setText(f"LoRa link: NO SIGNAL ({age:.0f}s)")
            self.link_label.setStyleSheet("color: #FF3333; font-weight: bold;")
        else:
            self.link_label.setText("LoRa link: OK")
            self.link_label.setStyleSheet("color: #00FFCC; font-weight: bold;")

    # ---------------------------------------------------------
    # PLOT HELPER
    # ---------------------------------------------------------
    @staticmethod
    def _finite(values):
        """NaN-safe filter: a channel that was not transmitted must not be able
        to destroy the axis range of a graph that does have data."""
        out = []
        for v in values:
            try:
                f = float(v)
            except (TypeError, ValueError):
                continue
            if math.isfinite(f):
                out.append(f)
        return out

    @staticmethod
    def _autoscale(plot, x, series_list):
        xs = GroundStationGUI._finite(x)
        if len(xs) == 1:
            plot.setXRange(xs[0] - 5, xs[0] + 5, padding=0)
        elif len(xs) >= 2:
            xmin, xmax = min(xs), max(xs)
            if xmax <= xmin:
                xmax = xmin + 1
            pad = max((xmax - xmin) * 0.05, 0.5)
            plot.setXRange(xmin - pad, xmax + pad, padding=0)

        ys = GroundStationGUI._finite(v for s in series_list for v in s)
        if ys:
            lo, hi = min(ys), max(ys)
            if hi - lo < 1.0:
                c = (lo + hi) / 2
                lo, hi = c - 1.0, c + 1.0
            else:
                pad = (hi - lo) * 0.15
                lo, hi = lo - pad, hi + pad
            plot.setYRange(lo, hi, padding=0)

    # ---------------------------------------------------------
    # TELEMETRY HANDLER
    # ---------------------------------------------------------
    # ---------------------------------------------------------
    # SERIAL MONITOR HELPER (auto-scroll)
    # ---------------------------------------------------------
    def _log(self, text, color=None):
        """Append one line to the Serial Monitor and keep the newest visible.

        Implemented with insertHtml/insertPlainText (instead of
        QTextEdit.append) so the append point is always the end of the
        document and the scroll position is explicitly controlled by the
        "Auto-scroll Serial Monitor" switch.
        """
        try:
            cursor = self.console.textCursor()
            cursor.movePosition(cursor.MoveOperation.End)
            self.console.setTextCursor(cursor)
            if color:
                safe = (str(text).replace("&", "&amp;")
                        .replace("<", "&lt;").replace(">", "&gt;"))
                # white-space:pre keeps the column alignment of the receiver's
                # report block intact in the monitor.
                self.console.insertHtml(
                    f'<span style="color:{color}; white-space:pre">{safe}'
                    f'</span><br>')
            else:
                self.console.insertPlainText(str(text) + "\n")
            if getattr(self, "auto_scroll", True):
                sb = self.console.verticalScrollBar()
                sb.setValue(sb.maximum())
        except Exception:
            pass

    # ---------------------------------------------------------
    # TELEMETRY HANDLER  (runs on the GUI thread, from a queued signal)
    # ---------------------------------------------------------
    @staticmethod
    def _fmt(value, digits=2, suffix=""):
        """Render a channel, or '--' when the firmware did not transmit it."""
        try:
            f = float(value)
        except (TypeError, ValueError):
            return "--"
        if not math.isfinite(f):
            return "--"
        return f"{f:.{digits}f}{suffix}"

    def handle_telemetry_packet(self, pkt, packet_size):
        """The single place where a validated packet enters the GUI.

        Order of operations: store (single source) -> derived attitude ->
        graphs -> numeric readouts -> CSV -> Serial Monitor -> tabs.  Every
        widget update happens here, on the GUI thread; the worker thread only
        emits the dict.
        """
        try:
            # --- 1. one shared store -------------------------------------
            self.store.push(pkt)

            # --- 2. packet-loss bookkeeping (port of checkPacketLoss()) ---
            try:
                count = int(pkt.get("packet_count", 0))
            except (TypeError, ValueError):
                count = 0
            for _level, msg in self.packet_loss.update(count):
                self._log(msg, "#FF8A00")

            # --- 3. attitude derived from real accelerometer / gyro -------
            roll, pitch, yaw = self.attitude.update(pkt)
            if all(math.isfinite(v) for v in (roll, pitch, yaw)):
                pkt = dict(pkt)                 # do not mutate the stored one
                pkt["roll"], pkt["pitch"], pkt["yaw"] = roll, pitch, yaw
                self.derived = {"roll": roll, "pitch": pitch, "yaw": yaw}
                self.store.latest["roll"] = roll
                self.store.latest["pitch"] = pitch
                self.store.latest["yaw"] = yaw
                # store.push() already appended one NaN sample per channel for
                # this packet; overwrite that slot so every series keeps the
                # same length as the time axis (no second copy, no drift).
                for key, value in (("roll", roll), ("pitch", pitch), ("yaw", yaw)):
                    if self.hist[key]:
                        self.hist[key][-1] = value
                    else:
                        self.hist[key].append(value)
                self.attitude_indicator.set_attitude(pitch, roll, yaw)

            # --- 4. flight time axis --------------------------------------
            t_ms = pkt.get("time_ms")
            t = float(t_ms) / 1000.0 if self._finite([t_ms]) else float("nan")

            # --- 5. graphs: every channel goes to its own tile ------------
            x = list(self.hist["t"])
            for pid, lst in self.curves.items():
                for key, curve in lst:
                    series = list(self.hist[key])
                    if len(series) < len(x):
                        series = [float("nan")] * (len(x) - len(series)) + series
                    curve.setData(x, series)
                self._autoscale(self.plots[pid], x,
                                [self.hist[k] for k, _c in lst])
                note = self.plot_notes.get(pid)
                if note is not None and self.plot_note_text.get(pid):
                    has_data = any(self._finite(self.hist[k]) for k, _c in lst)
                    note.setVisible(not has_data)
            self._place_plot_notes()

            # --- 6. numeric readouts (NaN -> "--") ------------------------
            self.lbl_bmp.setText(
                f"Alt {self._fmt(pkt.get('bmp_alt'))} m | "
                f"{self._fmt(pkt.get('bmp_temp'))} °C | "
                f"{self._fmt(pkt.get('bmp_press'))} hPa")
            self.lbl_dps.setText(
                f"Alt {self._fmt(pkt.get('dps_alt'))} m | "
                f"{self._fmt(pkt.get('dps_temp'))} °C | "
                f"{self._fmt(pkt.get('dps_press'))} hPa")
            self.lbl_alt_diff.setText(
                "ΔAlt (BMP−DPS): "
                f"{self._fmt(pkt.get('alt_diff'), 2, ' m')}")
            if self._finite([pkt.get("bmp_alt")]):
                self.max_alt = max(self.max_alt if math.isfinite(self.max_alt)
                                   else float("-inf"),
                                   float(pkt["bmp_alt"]),
                                   float(pkt.get("dps_alt", float("nan")))
                                   if self._finite([pkt.get("dps_alt")])
                                   else float("-inf"))
            self.lbl_max_alt.setText(
                f"Max Alt: {self._fmt(self.max_alt) if math.isfinite(self.max_alt) else '0.00'} m")

            self.lbl_accel.setText(
                f"Accel: X {self._fmt(pkt.get('ax'))} | "
                f"Y {self._fmt(pkt.get('ay'))} | "
                f"Z {self._fmt(pkt.get('az'))} m/s²")
            self.lbl_gyro.setText(
                f"Gyro: X {self._fmt(pkt.get('gx'))} | "
                f"Y {self._fmt(pkt.get('gy'))} | "
                f"Z {self._fmt(pkt.get('gz'))} °/s")
            self.lbl_euler.setText(
                f"Roll {self._fmt(pkt.get('roll'), 1)}°* | "
                f"Pitch {self._fmt(pkt.get('pitch'), 1)}°* | "
                f"Yaw {self._fmt(pkt.get('yaw'), 1)}°*  (derived)")
            if self._finite([pkt.get("accel_mag")]):
                self.max_accel = max(self.max_accel, float(pkt["accel_mag"]))
            self.lbl_accel_mag.setText(
                f"|a|: {self._fmt(pkt.get('accel_mag'))} m/s² "
                f"(max {self._fmt(self.max_accel)})")

            vbus = pkt.get("vbus")
            low = self._finite([vbus]) and float(vbus) < LOW_VOLTAGE_WARN
            self.lbl_vbus.setText(
                f"Bus: {self._fmt(vbus)} V" + ("  ⚠ LOW" if low else ""))
            self.lbl_vbus.setStyleSheet(
                f"color: {'#FF3333' if low else '#B388FF'};"
                "font-size: 13pt; font-weight: bold;")
            self.lbl_cur.setText(
                f"Current: {self._fmt(pkt.get('cur'), 1)} mA")
            self.lbl_pwr.setText(
                f"Power: {self._fmt(pkt.get('pwr'), 1)} mW")

            # --- 7. link statistics ---------------------------------------
            self.packet_count = self.store.packet_count
            self.last_packet_wall = time.time()
            self.last_packet_size = packet_size
            self.total_packet_bytes += packet_size
            avg = (self.total_packet_bytes / self.packet_count
                   if self.packet_count else 0.0)
            elapsed = time.time() - self.start_wall
            rate = self.store.rate_hz()
            state = pkt.get("flight_state") or "--"
            color = FLIGHT_STATE_COLORS.get(state, "#888888")

            self.lbl_packet_count.setText(f"Packets: {self.packet_count}")
            self.lbl_packet_rate.setText(f"Rate: {rate:.2f} Hz")
            self.lbl_last_packet.setText(
                f"Last Packet: {time.strftime('%H:%M:%S')}")
            self.lbl_time.setText(
                f"Flight Time: {self._fmt(t) if math.isfinite(t) else '0.00'} s")
            self.lbl_packet_size.setText(f"Last Size: {packet_size} B")
            self.lbl_avg_size.setText(f"Average Size: {avg:.1f} B")
            self.status_label.setText(f"Status: CONNECTED — {state}")
            self.status_label.setStyleSheet(
                f"color: {color}; font-weight: bold;")

            # --- 8. map marker (only for a real GNSS fix) ------------------
            if "latitude" in pkt and "longitude" in pkt:
                self._update_map_location(pkt["latitude"], pkt["longitude"])

            # --- 9. CSV ----------------------------------------------------
            self.csv_logger.write(pkt)

            # --- 10. Serial Monitor ----------------------------------------
            self._log(ZPROTO.format_monitor_line(pkt), "#00FF00")

            # --- 11. the same dict drives the map and both simulations -----
            self._feed_new_tabs(pkt)

        except Exception as e:
            self._log(f"[TELEMETRY UI ERROR] {type(e).__name__}: {e}", "#FF3333")

    # ---------------------------------------------------------
    # PLOT NOTICES
    # ---------------------------------------------------------
    def _place_plot_notes(self):
        """Keep the "not transmitted" caption centred in its tile."""
        for pid, note in self.plot_notes.items():
            if not note.isVisible() or not self.plot_note_text.get(pid):
                continue
            try:
                (xmin, xmax), (ymin, ymax) = (
                    self.plots[pid].getViewBox().viewRange())
                note.setPos((xmin + xmax) / 2.0, (ymin + ymax) / 2.0)
            except Exception:
                pass

    # ---------------------------------------------------------
    # TOOLS: replay a log / hardware-in-the-loop self test
    # ---------------------------------------------------------
    def _on_replay(self):
        """Replay a saved receiver log through the *same* decoder."""
        path, _ = QFileDialog.getOpenFileName(
            self, "Open receiver log", "",
            "Logs and CSV (*.log *.txt *.csv);;All files (*)")
        if not path:
            return
        if self.thread is not None and self.thread.isRunning():
            QMessageBox.information(
                self, "Replay", "Disconnect the serial link before replaying.")
            return
        from zenith.serial_link import ReplayWorker
        self.decoder_replay = ReceiverDecoder()
        self.replay_worker = ReplayWorker(path, self.decoder_replay,
                                          speed=5.0)
        self.replay_worker.line_received.connect(
            lambda line: self._log(f"[RX] {line.rstrip()}", "#9E9E9E"))
        self.replay_worker.sample_decoded.connect(
            lambda pkt: self.handle_telemetry_packet(pkt, len(str(pkt))))
        self.replay_worker.message.connect(
            lambda level, text: self._log(
                text, "#FF8A00" if level == "warn" else "#9E9E9E"))
        self.replay_worker.start()

    def _on_hil(self):
        """Hardware-In-The-Loop self test.

        Pushes reference frames into the *open* port (PC -> RX Teensy USB ->
        this decoder).  It only verifies the plumbing; the frames are tagged
        ``_source='hil'`` and are never mistaken for flight telemetry.
        """
        if self.thread is None or not self.thread.isRunning():
            QMessageBox.information(
                self, "HIL Self-Test",
                "Connect to the receiver first - the self test sends frames "
                "into the open port and waits for them to come back.")
            return
        from zenith.transmitter import reference_frames
        frames = reference_frames(5, 1.0)
        self.hil_frames = {"sent": len(frames), "ok": 0,
                           "pending": list(frames)}
        for frame in frames:
            self.thread.send(frame)
        self._log(f"[HIL] sent {len(frames)} reference frames; "
                  f"waiting for the decoder ...", "#FFD400")

    # ---------------------------------------------------------
    def closeEvent(self, event):
        # Stop the worker thread first (it owns the port), then flush the log.
        if self.thread is not None and self.thread.isRunning():
            self.thread.stop()
            self.thread = None
        worker = getattr(self, "replay_worker", None)
        if worker is not None and worker.isRunning():
            worker.stop()
            worker.wait(2000)
        try:
            self.csv_logger.close()
        except Exception:
            pass
        event.accept()


